+      && binding.runId === paths.expectedRunId
+      && binding.receiptId === receipt.receiptId
+      && typeof binding.storyId === 'string'
+      && typeof binding.reviewRunId === 'string'
+      && typeof binding.lane === 'string'
+      && typeof binding.importedAt === 'string'
