+    unlinkIfPresent(paths.prompt);
+    unlinkIfPresent(paths.environment);
+    if (managedReviewScratch) {
+      cleanupManagedReviewScratchForSubmitFailure(paths, managedReviewScratch, 'submit_input_setup');
