+    // failed terminal rather than deleting the run, so status/GC expose any
+    // retained scratch cleanup diagnostic and recovery anchor.
+    writeTerminal(
+      paths,
+      'failed',
+      `submit_input_write_failed:${error instanceof Error ? error.message : String(error)}`,
