+    throw new Error(`managed host run ${spec.runId}: partial runtime: immutable spec/owner/snapshot binding mismatch`);
+  }
+  const snapshotIsTerminal = ['completed', 'failed', 'cancelled', 'timed_out'].includes(snapshot.state);
