  if (pid === process.pid) return currentProcessStartTimeMs();
  if (process.platform === 'win32') return null;
  try {
    const raw = execFileSync('ps', ['-o', 'lstart=', '-p', String(pid)], {
      encoding: 'utf8',
      timeout: 1_000,
      stdio: ['ignore', 'pipe', 'ignore'],
